record.field:
{
  "type": "object",
  "properties": {
    "name": {
      "type": "string",
      "description": "Tên hoặc từ khóa sản phẩm (VD: Khoan FPD3, Bulong M12)"
    }
  },
  "required": ["name"]
}

{
  "type": "object",
  "properties": {
    "code": {"type": "string", "description": "Mã sản phẩm (viết liền, in hoa, không dấu)"},
    "name": {"type": "string", "description": "Tên sản phẩm chuẩn hóa đầy đủ"},
    "price": {"type": "number", "description": "Giá bán đề xuất (VNĐ)"},
    "price_pu": {"type": "number", "description": "Giá mua (VNĐ)"},
    "tax": {"type": "number", "description": "Thuế VAT (8 hoặc 10)"},
    "unit": {"type": "string", "description": "Đơn vị tính (Cái, Bộ, Hộp...)"},
    "category": {"type": "string", "description": "Tên nhóm hàng"},
    "category_id": {"type": "integer", "description": "ID nhóm hàng"},
    "type": {"type": "string", "enum": ["goods", "service", "finished_product"], "description": "Loại hàng hóa"}
  },
  "required": ["code", "name", "price", "tax", "unit", "category", "category_id", "type", "price_pu"]
}

{
  "type": "object",
  "properties": {
    "misa_id": {"type": "string", "description": "MISA product ID (GUID)"},
    "field": {"type": "string", "enum": ["name", "code", "unit_price_fixed", "purchased_price", "unit_price", "tax"], "description": "Trường cần cập nhật: name=tên, code=mã, unit_price_fixed=giá bán cố định, purchased_price=giá mua, unit_price=giá bán lẻ (gồm VAT), tax=thuế GTGT (truyền % VD: 10, 8)"},
    "new_value": {"type": "string", "description": "Giá trị mới"},
    "old_value": {"type": "string", "description": "Giá trị cũ (để đối chứng)"}
  },
  "required": ["misa_id", "field", "new_value", "old_value"]
}

{
  "type": "object",
  "properties": {
    "name": {"type": "string", "description": "Tên nhóm cần tìm (VD: Vật tư khí nén, Bảo hộ lao động...)"}
  },
  "required": ["name"]
}

{
  "type": "object",
  "properties": {
    "journal_memo": {"type": "string", "description": "Diễn giải hoặc mã chứng từ (VD: DH1255, PO0012)"},
    "limit": {"type": "integer", "description": "Số kết quả tối đa (mặc định 20)"}
  },
  "required": ["journal_memo"]
}
